// CacheDir return the effective cache directory path.
//
// This is `{base}/tree-sitter-language-pack/v{version}/libs/`, where `{base}` is
// either the custom BASE directory set via [`configure`] / [`init`]
// (`PackConfig::cache_dir`) or the platform default cache directory — both are
// suffixed identically, so a custom `cache_dir` is never used as the final libs
// path. The default resolves to `~/.cache/tree-sitter-language-pack/v{version}/libs/`
// on a typical Unix system.
//
// Errors are returned when returns an error if no cache directory can be resolved: `version` is somehow
// invalid, or (with no custom `cache_dir` configured) the platform reports none
// and `TREE_SITTER_LANGUAGE_PACK_CACHE_DIR` is unset. This crate no longer falls
// back to the temporary directory for the latter case — see #101 H2.
//
// Example:
//
//	let dir = cache_dir();
//	println!("Cache directory: {dir}");
func CacheDir() (string, error) {
	ptr := C.ts_pack_cache_dir()
	if err := lastError(); err != nil {
		if ptr != nil {
			C.ts_pack_free_string(ptr)
		}
		return "", err
	}
	defer C.ts_pack_free_string(ptr)
	return C.GoString(ptr), nil
}

// CleanCache delete all cached parser shared libraries.
//
// Resets the cache registration so the next call to [`get_language`] or
// a download function will re-register the (now empty) cache directory.
//
// Errors are returned when returns an error if the cache directory cannot be removed.
//
// Example:
//
//	clean_cache();
//	println!("Cache cleared");
func CleanCache() error {
	C.ts_pack_clean_cache()
	return lastError()
}

// Configure apply download configuration without downloading anything.
//
// Use this to set a custom cache directory before the first call to
// [`get_language`] or any download function. Changing the cache dir
// after languages have been registered has no effect on already-loaded
// languages.
//
// `PackConfig::cache_dir` is a BASE directory, not the final libs path: this
// crate appends `tree-sitter-language-pack/v{version}/libs` to it, the same
// suffix applied to the platform default cache directory. In the example below,
// files actually land under `/tmp/my-parsers/tree-sitter-language-pack/v{version}/libs/`,
// never directly in `/tmp/my-parsers/`. Call [`cache_dir`] to read back the
// resolved, fully-suffixed path.
//
// Errors are returned when returns an error if the lock cannot be acquired.
//
// Example:
//
//	let config = PackConfig {
//	    cache_dir: Some(PathBuf::from("/tmp/my-parsers")),
//	    languages: None,
//	    groups: None,
//	};
//	configure(&config);
func Configure(config PackConfig) error {
	jsonBytescConfig, err := json.Marshal(config)
	if err != nil {
		return fmt.Errorf("failed to marshal: %w", err)
	}
	// When the parameter is a nil pointer (Option<&T> on the Rust side), json.Marshal
	// emits "null" which the FFI's _from_json rejects. Substitute "{}" so a default
	// instance is constructed instead — semantically equivalent to None for query types
	// whose fields are all optional with serde(default).
	if string(jsonBytescConfig) == "null" {
		jsonBytescConfig = []byte("{}")
	}
	tmpStrcConfig := C.CString(string(jsonBytescConfig))
	cConfig := C.ts_pack_pack_config_from_json(tmpStrcConfig)
	C.free(unsafe.Pointer(tmpStrcConfig))
	if cConfig == 0 {
		return fmt.Errorf("failed to create pack_config: %s", C.GoString(C.ts_pack_last_error_context()))
	}
	defer C.ts_pack_pack_config_free(cConfig)

	C.ts_pack_configure(cConfig)
	return lastError()
}

