// Download specific languages to the local cache.
//
// Returns the number of distinct languages available after the call. Already
// compiled or cached languages are included in the count.
//
// Aliases are resolved before counting, so `["shell", "bash"]` names one
// language and returns 1.
//
// Errors are returned when returns an error if any language is not available in the manifest or if
// the download fails.
//
// Example:
//
//	let count = download(&["python", "rust", "typescript"]);
//	println!("Ensured {} languages", count);
func Download(names []string) (uint, error) {
	jsonBytescNames, err := json.Marshal(names)
	if err != nil {
		return 0, fmt.Errorf("failed to marshal: %w", err)
	}
	// A nil Go slice or map marshals to "null", while a non-nil empty one marshals to
	// "[]" — the form serde_json writes for an empty Rust collection, and the only
	// one the FFI's from_str accepts. Normalise so both spellings of "empty" cross the ABI
	// identically.
	if string(jsonBytescNames) == "null" {
		jsonBytescNames = []byte("[]")
	}
	cNames := C.CString(string(jsonBytescNames))
	defer C.free(unsafe.Pointer(cNames))

	ptr := C.ts_pack_download(cNames)
	if err := lastError(); err != nil {
		return 0, err
	}
	return uint(ptr), nil
}

// DownloadAll download all available languages from the remote manifest.
