// GetLanguage get a tree-sitter [`Language`] by name using the global registry.
//
// Resolves language aliases (e.g., `"shell"` maps to `"bash"`).
// When the `download` feature is enabled (default), automatically downloads
// the parser from GitHub releases if not found locally.
//
// Errors are returned when returns [`Error::LanguageNotFound`] if the language is not recognized,
// or [`Error::Download`] if auto-download fails.
//
// Example:
//
//	let _lang = get_language("python")?;
//	let mut parser = Parser::new();
//	parser.set_language("python")?;
//	let tree = parser.parse("x = 1")/* error: parse failed");
//	assert_eq!(tree.root_node().kind(), "module");
//	# Ok::<(), tree_sitter_language_pack::Error>(())
func GetLanguage(name string) (*tree_sitter.Language, error) {
	cName := C.CString(name)
	defer C.free(unsafe.Pointer(cName))

	cLang := C.ts_pack_get_language(cName)
	if err := lastError(); err != nil {
		return nil, err
	}
	return tree_sitter.NewLanguage(unsafe.Pointer(cLang)), nil
}

// GetLocalsQuery get the locals query for a language, if bundled.
//
// Returns the contents of `locals.scm` as a static string, or `None`
// if no locals query is bundled for this language.
//
// Example:
//
//	let query = get_locals_query("python");
//	// Returns None for languages without bundled locals queries
//	let missing = get_locals_query("nonexistent_lang");
//	assert!(missing.is_none());
func GetLocalsQuery(language string) *string {
	cLanguage := C.CString(language)
	defer C.free(unsafe.Pointer(cLanguage))

	ptr := C.ts_pack_get_locals_query(cLanguage)
	return func() *string {
		if ptr == nil {
			return nil
		}
		defer C.ts_pack_free_string(ptr)
		s := C.GoString(ptr)
		return &s
	}()
}

// GetParser get a [`Parser`] pre-configured for the given language.
//
// This is a convenience function that calls [`get_language`] and configures
// a new parser in one step.
//
// Errors are returned when returns [`Error::LanguageNotFound`] if the language is not recognized, or
// [`Error::ParserSetup`] if the language cannot be applied to the parser.
//
// Example:
//
//	let mut parser = get_parser("rust")?;
//	let tree = parser.parse("fn main() {}")/* error: parse failed");
//	assert!(!tree.root_node().has_error());
//	# Ok::<(), tree_sitter_language_pack::Error>(())
func GetParser(name string) (*Parser, error) {
	cName := C.CString(name)
	defer C.free(unsafe.Pointer(cName))

	ptr := C.ts_pack_get_parser(cName)
	if err := lastError(); err != nil {
		if ptr != 0 {
			C.ts_pack_parser_free(ptr)
		}
		return nil, err
	}
	return &Parser{ptr: ptr}, nil
}

