// HasLanguage check if a language is available by name or alias.
//
// Returns `true` if the language can be loaded (statically compiled,
// dynamically available, or a known alias for one of these).
//
// Example:
//
//	assert!(has_language("python"));
//	assert!(has_language("shell")); // alias for "bash"
//	assert!(!has_language("nonexistent_language"));
func HasLanguage(name string) bool {
	cName := C.CString(name)
	defer C.free(unsafe.Pointer(cName))

	ptr := C.ts_pack_has_language(cName)
	return ptr != 0
}

// Init ialize the language pack with the given configuration.
//
// Applies any custom cache directory, then downloads all languages and groups
// specified in the config. This is the recommended entry point when you want
// to pre-warm the cache before use.
//
// Errors are returned when returns an error if configuration cannot be applied or if downloads fail.
//
// Example:
//
//	let config = PackConfig {
//	    cache_dir: None,
//	    languages: Some(vec!["python".to_string(), "rust".to_string()]),
//	    groups: None,
//	};
//	init(&config);
func Init(config PackConfig) error {
	jsonBytescConfig, err := json.Marshal(config)
	if err != nil {
		return fmt.Errorf("failed to marshal: %w", err)
	}
	// When the parameter is a nil pointer (Option<&T> on the Rust side), json.Marshal
	// emits "null" which the FFI's _from_json rejects. Substitute "{}" so a default
	// instance is constructed instead — semantically equivalent to None for query types
	// whose fields are all optional with serde(default).
	if string(jsonBytescConfig) == "null" {
		jsonBytescConfig = []byte("{}")
	}
	tmpStrcConfig := C.CString(string(jsonBytescConfig))
	cConfig := C.ts_pack_pack_config_from_json(tmpStrcConfig)
	C.free(unsafe.Pointer(tmpStrcConfig))
	if cConfig == 0 {
		return fmt.Errorf("failed to create pack_config: %s", C.GoString(C.ts_pack_last_error_context()))
	}
	defer C.ts_pack_pack_config_free(cConfig)

	C.ts_pack_init(cConfig)
	return lastError()
}

// LanguageCount return the number of available languages.
//
// Includes statically compiled languages, dynamically loadable languages,
