//	println!("{} languages available", count);
func LanguageCount() uint {
	ptr := C.ts_pack_language_count()
	return uint(ptr)
}

// ManifestGroups return the names of every language group the remote manifest defines, sorted.
//
// Group names are manifest data, not a compile-time constant of this crate, so
// this is the only reliable way to learn what [`download_group`] and
// [`PackConfig::groups`] accept. The published manifest currently defines just
// `"all"`.
//
// Errors are returned when returns [`Error::Download`] if the manifest cannot be fetched.
//
// Example:
//
//	for group in manifest_groups()? {
//	    println!("{group}");
//	}
//	# Ok::<(), tree_sitter_language_pack::Error>(())
func ManifestGroups() ([]string, error) {
	ptr := C.ts_pack_manifest_groups()
	if err := lastError(); err != nil {
		return nil, err
	}
	if ptr == nil {
		return nil, fmt.Errorf("failed to get result")
	}
	defer C.ts_pack_free_string(ptr)
	var result []string
	if err := json.Unmarshal([]byte(C.GoString(ptr)), &result); err != nil {
		return nil, fmt.Errorf("failed to unmarshal: %w", err)
	}
	return result, nil
}

// ManifestLanguages return all language names available in the remote manifest (371).
