//	println!("{} languages available for download", langs.len());
func ManifestLanguages() ([]string, error) {
	ptr := C.ts_pack_manifest_languages()
	if err := lastError(); err != nil {
		return nil, err
	}
	if ptr == nil {
		return nil, fmt.Errorf("failed to get result")
	}
	defer C.ts_pack_free_string(ptr)
	var result []string
	if err := json.Unmarshal([]byte(C.GoString(ptr)), &result); err != nil {
		return nil, fmt.Errorf("failed to unmarshal: %w", err)
	}
	return result, nil
}

// Prefetch grammars: download any not already loadable from disk, then load every
// requested language into the process registry so a subsequent hot loop only parses.
//
// Unlike [`download()`], this does not trust in-memory availability — it downloads
// whenever a grammar is not actually loadable from disk (fixing the case where a
// known-but-not-downloaded grammar is reported present), then resolves and caches
// every requested language. Call it once, up front, before a parallel workload.
//
// Errors are returned when returns [`Error::Download`] if a required grammar cannot be fetched, or
// [`Error::LanguageNotFound`] if a requested name is unknown.
//
// Example:
//
//	prefetch(&["rust", "python", "go"])?;
//	# Ok::<(), tree_sitter_language_pack::Error>(())
func Prefetch(languages []string) error {
	jsonBytescLanguages, err := json.Marshal(languages)
	if err != nil {
		return fmt.Errorf("failed to marshal: %w", err)
	}
	// A nil Go slice or map marshals to "null", while a non-nil empty one marshals to
	// "[]" — the form serde_json writes for an empty Rust collection, and the only
	// one the FFI's from_str accepts. Normalise so both spellings of "empty" cross the ABI
	// identically.
	if string(jsonBytescLanguages) == "null" {
		jsonBytescLanguages = []byte("[]")
	}
	cLanguages := C.CString(string(jsonBytescLanguages))
	defer C.free(unsafe.Pointer(cLanguages))

	C.ts_pack_prefetch(cLanguages)
	return lastError()
}

// Process source code and extract file intelligence using the global registry.
//
// Parses the source with tree-sitter and extracts metrics, structure, imports,
// exports, comments, docstrings, symbols, diagnostics, and/or chunks based on
// the flags set in [`ProcessConfig`].
//
// Errors are returned when returns [`Error::InvalidRange`] if the config carries a zero-valued limit or
// the source exceeds [`ProcessConfig::max_source_bytes`],
// [`Error::ParseTimeout`] if the parse exceeds
// [`ProcessConfig::parse_timeout_ms`], [`Error::LanguageNotFound`] if the
// language is unknown, or [`Error::ParseFailed`] if parsing yields no tree.
//
// Example:
//
//	let config = ProcessConfig::new("python").all();
//	let result = process("def hello(): pass", &config);
//	println!("Language: {}", result.language);
//	println!("Lines: {}", result.metrics.total_lines);
//	println!("Structures: {}", result.structure.len());
func Process(source string, config ProcessConfig) (*ProcessResult, error) {
	cSource := C.CString(source)
	defer C.free(unsafe.Pointer(cSource))

	jsonBytescConfig, err := json.Marshal(config)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal: %w", err)
	}
	// When the parameter is a nil pointer (Option<&T> on the Rust side), json.Marshal
	// emits "null" which the FFI's _from_json rejects. Substitute "{}" so a default
	// instance is constructed instead — semantically equivalent to None for query types
	// whose fields are all optional with serde(default).
	if string(jsonBytescConfig) == "null" {
		jsonBytescConfig = []byte("{}")
	}
	tmpStrcConfig := C.CString(string(jsonBytescConfig))
	cConfig := C.ts_pack_process_config_from_json(tmpStrcConfig)
	C.free(unsafe.Pointer(tmpStrcConfig))
	if cConfig == 0 {
		return nil, fmt.Errorf("failed to create process_config: %s", C.GoString(C.ts_pack_last_error_context()))
	}
	defer C.ts_pack_process_config_free(cConfig)

	ptr := C.ts_pack_process(cSource, cConfig)
	if err := lastError(); err != nil {
		if ptr != 0 {
			C.ts_pack_process_result_free(ptr)
		}
		return nil, err
	}
	defer C.ts_pack_process_result_free(ptr)
	jsonPtr := C.ts_pack_process_result_to_json(ptr)
	if jsonPtr == nil {
		return nil, fmt.Errorf("failed to convert to JSON")
	}
	defer C.ts_pack_free_string(jsonPtr)
	var result ProcessResult
	if err := json.Unmarshal([]byte(C.GoString(jsonPtr)), &result); err != nil {
		return nil, fmt.Errorf("failed to unmarshal: %w", err)
	}
	return &result, nil
}

