// New construct a new parser with no language set and no parse limits.
//
// Call [`Parser::set_language`] before parsing. Limits are opt-in via
// [`set_max_source_bytes`](Self::set_max_source_bytes) and
// [`set_parse_timeout_ms`](Self::set_parse_timeout_ms); both default to
// unbounded so that existing callers are unaffected.
func ParserNew() *Parser {
	ptr := C.ts_pack_parser_new()
	return &Parser{ptr: ptr}
}

// SetMaxSourceBytes refuse to parse sources longer than `max_bytes`.
//
// `None` (the default) means no limit. Over-limit input makes
// [`parse`](Self::parse) and [`parse_bytes`](Self::parse_bytes) return
// `None` after emitting a `WARN`; input is never silently truncated.
//
// See [`RECOMMENDED_MAX_SOURCE_BYTES`](crate::process_config::RECOMMENDED_MAX_SOURCE_BYTES).
func (h *Parser) SetMaxSourceBytes(maxBytes *uint) {
	var cMaxBytes C.size_t = C.size_t(^uint(0))
	if maxBytes != nil {
		cMaxBytes = C.size_t(uint(*maxBytes))
	}

	C.ts_pack_parser_set_max_source_bytes(h.ptr, cMaxBytes)
}

// SetParseTimeoutMs cancel a parse that exceeds `timeout_ms` milliseconds of wall clock.
//
// `None` (the default) means no budget. Cancellation runs through
// tree-sitter's parse progress callback, so it is granular to that
// callback's interval rather than exact.
//
// See [`RECOMMENDED_PARSE_TIMEOUT_MS`](crate::process_config::RECOMMENDED_PARSE_TIMEOUT_MS).
func (h *Parser) SetParseTimeoutMs(timeoutMs *uint64) {
	var cTimeoutMs C.uint64_t = C.uint64_t(^uint64(0))
	if timeoutMs != nil {
		cTimeoutMs = C.uint64_t(uint64(*timeoutMs))
	}

	C.ts_pack_parser_set_parse_timeout_ms(h.ptr, cTimeoutMs)
}

// SetLanguage configure the parser to use the language identified by name (e.g. `"python"`).
//
// Resolves the language through the global registry — auto-downloading
// if necessary, when the `download` feature is enabled.
//
// Errors are returned when returns [`Error::LanguageNotFound`] if the language is not recognized,
// or [`Error::ParserSetup`] if the language ABI is incompatible.
func (h *Parser) SetLanguage(name string) error {
	cName := C.CString(name)
	defer C.free(unsafe.Pointer(cName))

	C.ts_pack_parser_set_language(h.ptr, cName)
	return lastError()
}

// Parse a UTF-8 source string.
//
// Returns `None` if no language is set, if the parse was cancelled by the
// configured [timeout](Self::set_parse_timeout_ms), or if the source
// exceeds the configured [size limit](Self::set_max_source_bytes). Each
// non-parse outcome is logged, so an empty result is never silent.
//
// # Concurrency
//
// Parsing runs fully in parallel across threads for almost every language — no lock is
// taken. The exception is the small set of grammars whose external scanner keeps mutable
// process-global state (currently just `properties`): parses of that language are
// serialized against each other through an internal per-language lock, so that concurrent
// threads can't corrupt shared scanner state. Every other language is unaffected by that
// lock and never waits on it.
func (h *Parser) Parse(source string) *Tree {
	cSource := C.CString(source)
	defer C.free(unsafe.Pointer(cSource))

	ptr := C.ts_pack_parser_parse(h.ptr, cSource)
	return &Tree{ptr: ptr}
}

// ParseBytes parse a raw byte slice.
//
// Same outcomes as [`parse`](Self::parse), including the concurrency behaviour documented
// there.
func (h *Parser) ParseBytes(source []byte) *Tree {
	var cSource *C.uint8_t
	if len(source) > 0 {
		var cSourcePinner runtime.Pinner
		cSourcePinner.Pin(&source[0])
		defer cSourcePinner.Unpin()
		cSource = (*C.uint8_t)(unsafe.Pointer(&source[0]))
	}
	cSourceLen := C.uintptr_t(len(source))

	ptr := C.ts_pack_parser_parse_bytes(h.ptr, cSource, cSourceLen)
	return &Tree{ptr: ptr}
}

// Reset internal state. The next call to [`parse`](Self::parse) will
// not be incremental.
func (h *Parser) Reset() {
	C.ts_pack_parser_reset(h.ptr)
}

// WithChunking enable chunking with the given maximum chunk size in bytes.
func (r *ProcessConfig) WithChunking(maxSize uint) (*ProcessConfig, error) {
	cMaxSize := C.size_t(uint(maxSize))

	jsonBytesRecv, err := json.Marshal(r)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal receiver: %w", err)
	}
	tmpStrRecv := C.CString(string(jsonBytesRecv))
	cRecv := C.ts_pack_process_config_from_json(tmpStrRecv)
	C.free(unsafe.Pointer(tmpStrRecv))
	if cRecv == 0 {
		return nil, fmt.Errorf("failed to create receiver: %s", C.GoString(C.ts_pack_last_error_context()))
	}
	ptr := C.ts_pack_process_config_with_chunking(cRecv, cMaxSize)
	defer C.ts_pack_process_config_free(ptr)
	return func() *ProcessConfig {
		jsonPtr := C.ts_pack_process_config_to_json(ptr)
		if jsonPtr == nil {
			return nil
		}
		defer C.ts_pack_free_string(jsonPtr)
		var result ProcessConfig
		if err := json.Unmarshal([]byte(C.GoString(jsonPtr)), &result); err != nil {
			return nil
		}
		return &result
	}(), nil
}

// All enable every analysis feature, including data extraction.
