// Validate check that the configured limits are usable before they drive a parse.
//
// Called by `process` and
// [`LanguageRegistry::process`](crate::LanguageRegistry::process); call it
// directly to reject a bad configuration early.
//
// Errors are returned when returns [`Error::InvalidRange`](crate::Error::InvalidRange) when
// `chunk_max_size`, `max_source_bytes`, or `parse_timeout_ms` is `Some(0)`.
// Zero is always a configuration mistake: `None` is how each of these is
// disabled, so `Some(0)` could only mean "produce nothing".
func (r *ProcessConfig) Validate() error {
	jsonBytesRecv, err := json.Marshal(r)
	if err != nil {
		return fmt.Errorf("failed to marshal receiver: %w", err)
	}
	tmpStrRecv := C.CString(string(jsonBytesRecv))
	cRecv := C.ts_pack_process_config_from_json(tmpStrRecv)
	C.free(unsafe.Pointer(tmpStrRecv))
	if cRecv == 0 {
		return fmt.Errorf("failed to create receiver: %s", C.GoString(C.ts_pack_last_error_context()))
	}
	defer C.ts_pack_process_config_free(cRecv)
	C.ts_pack_process_config_validate(cRecv)
	jsonPtrUpdated := C.ts_pack_process_config_to_json(cRecv)
	if jsonPtrUpdated != nil {
		_ = json.Unmarshal([]byte(C.GoString(jsonPtrUpdated)), r)
		C.ts_pack_free_string(jsonPtrUpdated)
	}
	return lastError()
}

// RootNode return the root [`Node`] of this tree.
func (h *Tree) RootNode() *Node {
	ptr := C.ts_pack_tree_root_node(h.ptr)
	return &Node{ptr: ptr}
}

// Walk return a [`TreeCursor`] positioned at the root.
func (h *Tree) Walk() *TreeCursor {
	ptr := C.ts_pack_tree_walk(h.ptr)
	return &TreeCursor{ptr: ptr}
}

// Node return the [`Node`] at the cursor's current position.
func (h *TreeCursor) Node() *Node {
	ptr := C.ts_pack_tree_cursor_node(h.ptr)
	return &Node{ptr: ptr}
}

// GotoFirstChild move the cursor to the first child of the current node.
// Returns `true` if a child existed.
func (h *TreeCursor) GotoFirstChild() bool {
	ptr := C.ts_pack_tree_cursor_goto_first_child(h.ptr)
	return ptr != 0
}

// GotoParent move the cursor to the parent of the current node.
// Returns `true` if a parent existed.
func (h *TreeCursor) GotoParent() bool {
	ptr := C.ts_pack_tree_cursor_goto_parent(h.ptr)
	return ptr != 0
}

// GotoNextSibling move the cursor to the next sibling of the current node.
// Returns `true` if a sibling existed.
func (h *TreeCursor) GotoNextSibling() bool {
	ptr := C.ts_pack_tree_cursor_goto_next_sibling(h.ptr)
	return ptr != 0
}

// FieldName return the field name for the current node, if any.
func (h *TreeCursor) FieldName() *string {
	ptr := C.ts_pack_tree_cursor_field_name(h.ptr)
	return func() *string {
		if ptr == nil {
			return nil
		}
		defer C.ts_pack_free_string(ptr)
		s := C.GoString(ptr)
		return &s
	}()
}
